// === Tab: mySketch ===
p5.disableFriendlyErrors = true;

let vs = `
  precision highp float;

  attribute vec3 aPosition;

  void main() {
     vec4 positionVec4 = vec4(aPosition, 1.0);

     gl_Position = positionVec4;
}
`;
let fs = `
  precision highp float;

  uniform vec2 resolution;
  uniform float freq;
	uniform float freq1;
	uniform float points[50];

	float modulus(float a,float b)
	{
		return a - (b * floor(a/b));
	}

	float smoothMin(float a,float b)
	{
		float k = 0.0001;
		return ((a+b) - sqrt(((a-b)*(a-b))+k)) / 2.0;
	}

  void main() {
    vec3 color;
		vec2 uv = vec2((gl_FragCoord.x - resolution.x/2.0) / resolution.x, (gl_FragCoord.y-resolution.y/2.0) / resolution.x);
		float closest = 10000.0;
		for (int i = 0; i < 25; i++)
		{
			float thisDistance = length(uv - vec2(points[i*2], points[(i*2)+1]));
			closest = smoothMin(thisDistance, closest);
		}
		float c = modulus(closest+freq, 0.05)*5.0;
    gl_FragColor = vec4(c+(0.5*cos(uv.x+freq1)),c+(0.5*sin(uv.y+freq1)),c*(uv.x)+0.2,1.0);
}
`;

let sh;

function setup() {
	createCanvas(1112, 834, WEBGL);
	background(100);
	sh = createShader(vs,fs)
}

function lerp(v0, v1, t) {
  return v0*(1-t)+v1*t
}

var points = [];
var vels = [];
function MakePoints()
{
	points = [];
	for (var i = 0; i < 25; i++)
	{
		points.push(Math.random()-0.5);
		vels.push(Math.random()-0.5);
	}
}
function RandomVels()
{
	vels = []
	for (var i = 0; i < points.length; i++)
	{
		vels.push(Math.random()-0.5);
	}
}
function ShiftPoints()
{
	var tempPoints = points;
	points = [];
	for (var i = 0; i < tempPoints.length; i++)
	{
		//var newP = tempPoints[i]+((Math.random()-0.5)*moveSpeed);
		var thisP = tempPoints[i]+(vels[i]*moveSpeed);
		thisP = min(max(-1,thisP),1);
		points.push(thisP);
	}
}
MakePoints();
var a = 0.005;
var t = 0;
var moveSpeed = 0.006;
function draw() {
	ShiftPoints();
	t++;
	if (t%500 == 0)
		RandomVels();
	a-=0.0003;
	shader(sh);
  sh.setUniform('resolution', [width, height]);
	sh.setUniform("freq", a);
	sh.setUniform("freq1", t*0.001);
	sh.setUniform("points", points);
	quad(-1, -1, -1, 1, 1, 1, 1, -1);
	resetShader();
}

//save JPG
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

